.target-card.active {
  border-color: var(--primary-blue);
  background: rgba(37, 99, 235, 0.08);
  box-shadow: 0 0 10px rgba(37, 99, 235, 0.15);
}

/* ==================== [ROLE: PIMPINAN CABANG] STYLING ==================== */
.badge-branch-header {
  display: inline-block;
  background: linear-gradient(135deg, #0ea5e9 0%, #0284c7 100%);
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  padding: 3px 12px;
  border-radius: 20px;
  letter-spacing: 0.3px;
  box-shadow: 0 2px 6px rgba(2, 132, 199, 0.3);
}

.pincab-metrics-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 16px;
  margin-top: 18px;
}

.pincab-stat-card {
  background: var(--card-bg, #ffffff);
  border: 1px solid var(--border-color, #e2e8f0);
  border-radius: var(--border-radius-md, 12px);
  padding: 18px 20px;
  display: flex;
  align-items: center;
  gap: 16px;
  box-shadow: var(--shadow-sm, 0 1px 3px rgba(0,0,0,0.05));
  transition: all 0.2s ease;
}

.pincab-stat-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md, 0 4px 12px rgba(0,0,0,0.08));
}

.pincab-stat-card.mini {
  display: block;
  padding: 16px;
}

.pincab-stat-card.alert-card {
  border-left: 4px solid #ef4444;
  background: #fffafa;
}

.pincab-stat-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.pincab-stat-icon.icon-blue { background: #eff6ff; color: #2563eb; }
.pincab-stat-icon.icon-green { background: #f0fdf4; color: #16a34a; }
.pincab-stat-icon.icon-purple { background: #faf5ff; color: #9333ea; }
.pincab-stat-icon.icon-gold { background: #fefce8; color: #ca8a04; }

.pincab-stat-body {
  flex: 1;
}

.pincab-stat-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted, #64748b);
  display: block;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}

.pincab-stat-val {
  font-size: 22px;
  font-weight: 800;
  color: var(--primary-navy, #0f172a);
  margin: 4px 0 2px;
  line-height: 1.2;
}

.pincab-stat-val .stat-unit {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-muted);
}

.pincab-stat-sub {
  font-size: 11.5px;
  color: var(--text-muted, #64748b);
  display: flex;
  align-items: center;
  gap: 5px;
}

.badge-dot-green {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #10b981;
  display: inline-block;
}

.badge-status-lulus {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: #dcfce7;
  color: #15803d;
  font-size: 11.5px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
}

.badge-status-proses {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: #fef3c7;
  color: #b45309;
  font-size: 11.5px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
}

.badge-status-belum {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: #f1f5f9;
  color: #64748b;
  font-size: 11.5px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 20px;
}

.pincab-rank-badge {
  display: inline-block;
  width: 28px;
  height: 28px;
  line-height: 28px;
  text-align: center;
  border-radius: 50%;
  font-weight: 800;
  font-size: 13px;
}
.pincab-rank-badge.rank-1 { background: #fef08a; color: #854d0e; }
.pincab-rank-badge.rank-2 { background: #e2e8f0; color: #334155; }
.pincab-rank-badge.rank-3 { background: #fed7aa; color: #9a3412; }
.pincab-rank-badge.rank-other { background: #f1f5f9; color: #64748b; }

.pincab-matrix-table td {
  vertical-align: middle;
}

