+        const l4Status = a.certifications && a.certifications.level4 ? a.certifications.level4.status : 'Belum Mengambil';
+
+        if (statusFilter === 'pending_only') {
+            matchStatus = (l3Status !== 'Lulus') || (l4Status !== 'Lulus');
+        } else if (statusFilter === 'l3_lulus') {
+            matchStatus = (l3Status === 'Lulus');
