+            matchStatus = (l4Status === 'Lulus');
+        } else if (statusFilter === 'unregistered') {
+            matchStatus = (l3Status === 'Belum Mengambil' || l4Status === 'Belum Mengambil');
+        }
+
+        return matchQuery && matchStatus;
+    });
+
+    if (filtered.length === 0) {
+        tbody.innerHTML = `<tr><td colspan="6" style="text-align:center; padding:24px; color:var(--text-muted);">Tidak ada agen yang cocok dengan kriteria pencarian & filter.</td></tr>`;
