window.submitTrainingPretest = function(e) {
    if (e) e.preventDefault();

    if (!currentPretestTrainingId) {
        window.hideTrainingPretestModal();
        return;
    }

    const trainings = JSON.parse(localStorage.getItem("pa_trainings")) || [];
