        if (!selected) {
            allAnswered = false;
        } else if (selected.value === q.correct) {
            correctCount++;
        }
    });

    if (!allAnswered) {
        if (window.showToast) window.showToast("Mohon jawab seluruh 3 soal Pre-Test.", "warning");
